      svg: '<svg viewBox="0 0 280 90" width="100%" style="max-width:280px;height:auto" xmlns="http://www.w3.org/2000/svg"><g stroke="currentColor" stroke-width="1" fill="none"><rect x="10" y="10" width="80" height="70"/><rect x="100" y="10" width="80" height="70"/><rect x="190" y="10" width="80" height="70"/></g><g font-size="8" fill="currentColor" text-anchor="middle"><text x="50" y="30">1:1</text><text x="50" y="50">min 1-2</text><text x="140" y="30">1:N</text><text x="140" y="50">always 2</text><text x="230" y="30">M:N</text><text x="230" y="50">always 3</text></g></svg>'
